mapper.insert:
INSERT INTO "conversation_round_generated_file" (
    "creator_id", "modifier_id", "round_id", "file_resource_id", "source_turn_number",
    "output_order", "generation_attempt_id", "output_kind", "output_status"
) VALUES (
    #{creatorId}, #{modifierId}, #{roundId}, #{fileResourceId}, #{sourceTurnNumber},
    #{outputOrder}, #{generationAttemptId}, #{outputKind}, #{outputStatus}
)
ON CONFLICT ("round_id", "file_resource_id") DO NOTHING

mapper.select:
SELECT round."round_number" AS "roundNumber", file."id" AS "fileResourceId", file."file_id" AS "fileId", file."original_filename" AS "originalFilename", COALESCE(file."detected_mime_type", file."declared_mime_type") AS "mimeType", file."file_size" AS "fileSize", file."width" AS "width", file."height" AS "height", file."kind" AS "kind", file."status" AS "status", relation."output_kind" AS "outputKind", relation."output_status" AS "outputStatus", relation."source_turn_number" AS "sourceTurnNumber", relation."output_order" AS "outputOrder" FROM "conversation_round_generated_file" relation INNER JOIN "conversation_round" round ON round."id" = relation."round_id" INNER JOIN "file_resource" file ON file."id" = relation."file_resource_id" WHERE round."conversation_id" = #{conversationId} AND round."round_number" <= #{endRoundNumber} AND round."status" = 'COMPLETED' AND round."deleted" = FALSE AND file."deleted" = FALSE AND file."file_id" IN
#{fileId}
ORDER BY ARRAY_POSITION( ARRAY[
CAST(#{fileId} AS VARCHAR)
], file."file_id")

mapper.update:
UPDATE "conversation_round_generated_file"
SET "output_status" = 'SUPERSEDED',
    "modifier_id" = #{userId}
WHERE "round_id" = #{roundId}
  AND "file_resource_id" IN

    #{fileResourceId}

  AND "output_status" = 'ACTIVE'
